KG42.register("clusters-588ed3d1ca6851cd04911464",{"id":"23-hierarchical_market_structure::v142-d-CL001","paper":"23-hierarchical_market_structure","label":"Microgrid participation boundary and conditional energy-supply declaration","record":{"cluster_id":"v142-d-CL001","label":"Microgrid participation boundary and conditional energy-supply declaration","market_meaning":"Under the hierarchical market arrangement of this paper, microgrids participate in DNEM energy trading, declare surplus generation or total generation capability according to the selected policy, and adopt the bid construction and strategy bounds given in the chain; the total-capacity policy also includes a participation mode that meets local demand from the distribution network.","mechanism_ids":["v141-a-M01"],"market_types":["DEM","LEM_DEM"],"process_stages":["bidding","participation"],"scope_disposition":"conditional","scope_explanation":"The two supply-demand policies are retained separately; R003 only supplements the demand-side arrangement of the total-capacity policy. R010's statement that direct participation in WEM is not applicable is limited to the technical and commercial context of this paper and is not extended to a general legal prohibition. DEM and LEM_DEM are retained as original chain scope labels. This cluster covers participation and declaration under the given policies and strategies and does not claim to complete policy selection or revenue optimization.","assembly_status":"assembled","boundary_rationale":"The participation boundary, traded product, supply-demand policy and bid construction jointly explain where a microgrid can declare what and how the declaration is formed; clearing, cross-market trading and settlement have independent decisions and results and are placed in separate Rule-Clusters.","chain_bindings":[{"chain_id":"v141-c-R010","ownership":"primary","role":"core","rationale":"Specifies the scope boundary for microgrid participation in DNEM and direct participation in WEM in this paper."},{"chain_id":"v141-c-R001","ownership":"primary","role":"core","rationale":"Provides supply declarations under the two policies and the shared bid construction."},{"chain_id":"v141-c-R003","ownership":"primary","role":"support","rationale":"Supplements the local-demand supply mode corresponding to the total-capacity declaration policy."},{"chain_id":"v141-c-R005","ownership":"primary","role":"context","rationale":"Defines the energy product involved in the declaration; its product statement itself does not add operational dependencies or independent trading obligations."}],"connections":[{"connection_id":"v142-d-CN001","from_chain_id":"v141-c-R010","to_chain_id":"v141-c-R001","kind":"complementary_scope","from_refs":["v141-c-R010::phi::v141-c-R010-C001"],"to_refs":["v141-c-R001::phi::v141-c-R001-C001","v141-c-R001::phi::v141-c-R001-C002"],"evidence_ids":["v141-b-g01-E001","v141-b-g01-E008"],"rationale":"Microgrid DNEM participation in the same mechanism is concretely developed by the two supply policies; this is a complementarity between participation scope and declaration activity and does not add admission conditions."},{"connection_id":"v142-d-CN002","from_chain_id":"v141-c-R003","to_chain_id":"v141-c-R001","kind":"complementary_scope","from_refs":["v141-c-R003::phi::v141-c-R003-C001"],"to_refs":["v141-c-R001::phi::v141-c-R001-C002"],"evidence_ids":["v141-b-g01-E008"],"rationale":"The source places meeting local demand from the distribution network and total-generation-capability declaration under the same policy; the two chains respectively express the demand arrangement and the supply declaration, are not merged as duplicate constraints, and are not extended to the surplus policy."},{"connection_id":"v142-d-CN003","from_chain_id":"v141-c-R005","to_chain_id":"v141-c-R001","kind":"complementary_scope","from_refs":["v141-c-R005::phi::v141-c-R005-C001"],"to_refs":["v141-c-R001::phi::v141-c-R001-C001","v141-c-R001::phi::v141-c-R001-C002"],"evidence_ids":["v141-b-g01-E001","v141-b-g01-E008"],"rationale":"The DNEM energy product provides the commodity-scope background for the two generation-declaration policies; this association does not turn the product definition into an added precondition."}],"object_mappings":[],"gaps":[{"gap_id":"v142-d-CL001-G001","category":"upstream_missing","description":"The existing chains are sufficient to express qualitative participation and bid construction under the given policies and strategies, but do not provide the local-demand calculation for declarable surplus, the complete definitions of total and net quantities under the two policies, or a policy-selection or revenue-optimization model.","chain_ids":["v141-c-R001","v141-c-R003"],"object_refs":["v141-c-R001::x::v141-c-R001-X-Pm","v141-c-R001::phi::v141-c-R001-C001","v141-c-R001::phi::v141-c-R001-C002","v141-c-R003::phi::v141-c-R003-C001"],"evidence_ids":["v141-b-g01-E008"],"proposal_ids":[],"required_work":"If extended to declarable-quantity calculation or optimal-strategy rules, the upstream should clarify the demand and total/net quantity definitions and supplement the corresponding decision expressions; currently the qualitative policy scope is maintained."},{"gap_id":"v142-d-CL001-G002","category":"ontology_extension","description":"The existing definition of bidding.supply focuses on quantity submission, whereas R001 also carries the price-bid strategy and its bounds; the related strategy-node proposal remains unapproved.","chain_ids":["v141-c-R001"],"object_refs":["v141-c-R001::V::bidding.supply","v141-c-R001::x::v141-c-R001-X-psim","v141-c-R001::phi::v141-c-R001-C003","v141-c-R001::phi::v141-c-R001-C004"],"evidence_ids":["v141-b-g01-E008","v141-b-g03-e05"],"proposal_ids":["proposal:v141-b-g03-bidding-strategy"],"required_work":"Manually check the ontological boundary between price strategy and quantity submission; retain the current binding before the proposal is processed and do not insert new nodes."},{"gap_id":"v142-d-CL001-G003","category":"unverified_source","description":"This cluster uses candidate evidence permitted by the experiment; the related B entries remain unverified, and the participation policy and bid transcription have not been verified against independent source texts.","chain_ids":["v141-c-R001","v141-c-R003","v141-c-R005","v141-c-R010"],"object_refs":[],"evidence_ids":["v141-b-g01-E001","v141-b-g01-E003","v141-b-g01-E008"],"proposal_ids":[],"required_work":"Manual checking should verify the source and condition scope; assembled only means that the candidate assembly within the limited scope is established."}]},"rule_refs":["23-hierarchical_market_structure::v141-c-R010","23-hierarchical_market_structure::v141-c-R001","23-hierarchical_market_structure::v141-c-R003","23-hierarchical_market_structure::v141-c-R005"],"unresolved_rule_refs":[],"node_ids":["COMP-24f3cdbef9d7cdff","COMP-7f5e3dcddfa1014c","COMP-e80c3b7a1946ecd1","KG40-f19328f0aeb3d626"]});
